import 'dart:convert';

import 'package:gymia/data/sqlite_workout_repository.dart';
import 'package:gymia/domain/activity.dart';
import 'package:sqflite/sqflite.dart';

/// Synthetic, deliberately non-personal v4 database and v3 backup pair.
/// The returned IDs are generated by the legacy repository and serve as exact
/// before/after migration assertions; no real user database is checked in.
class TrackiaLegacyFixture {
  const TrackiaLegacyFixture({
    required this.path,
    required this.backupV3,
    required this.workoutId,
    required this.exerciseId,
    required this.setId,
    required this.activityId,
    required this.messageId,
    required this.original,
  });

  final String path;
  final String backupV3;
  final String workoutId;
  final String exerciseId;
  final String setId;
  final String activityId;
  final String messageId;
  final String original;

  static Future<TrackiaLegacyFixture> create({
    required DatabaseFactory factory,
    required String path,
  }) async {
    final at = DateTime(2026, 10, 1, 8);
    final repo = await SqliteWorkoutRepository.open(
      factory: factory,
      path: path,
      clock: () => at,
    );
    try {
      final workoutId = await repo.start('Sesión sintética');
      await repo.addExercise(workoutId, 'Sentadilla');
      final exerciseId = (await repo.load()).single.exercises.single.id;
      await repo.addSet(exerciseId, '42,5', '8');
      final setId = (await repo.load()).single.exercises.single.sets.single.id;
      final activityId = await repo.prepareActivity(
        ActivityDefinition(name: 'Movilidad', repeated: false, restSeconds: 0),
      );
      await repo.startInterval(activityId);
      await repo.stopInterval(activityId);
      const original = 'Movilidad de hombros; 8 minutos y sin molestias.';
      final messageId = await repo.recordActivityMessage(activityId, original);
      await repo.finishActivity(activityId, at);
      await repo.finish(workoutId);
      final backupV3 = await repo.createBackupJson();
      final backup = jsonDecode(backupV3) as Map<String, dynamic>;
      if (backup['version'] != 3) {
        throw StateError('La fixture debe conservar el formato v3.');
      }
      final fixture = TrackiaLegacyFixture(
        path: path,
        backupV3: backupV3,
        workoutId: workoutId,
        exerciseId: exerciseId,
        setId: setId,
        activityId: activityId,
        messageId: messageId,
        original: original,
      );
      return fixture;
    } finally {
      await repo.close();
      // Produce an actual v4 schema from the compatible legacy tables.
      final db = await factory.openDatabase(path);
      try {
        await db.execute('DROP TABLE IF EXISTS trackia_legacy_activity_scope');
        await db.execute('DROP TABLE IF EXISTS trackia_legacy_workout_scope');
        await db.execute('DROP TABLE IF EXISTS trackia_spaces');
        await db.setVersion(4);
      } finally {
        await db.close();
      }
    }
  }
}
